// Agreement defines model for Agreement.
type Agreement struct {
	// Body 正文（Markdown）
	Body          string        `json:"body"`
	ChangeSummary *string       `json:"change_summary,omitempty"`
	EffectiveAt   time.Time     `json:"effective_at"`
	Id            int64         `json:"id"`
	Kind          AgreementKind `json:"kind"`
	Title         string        `json:"title"`
	UpdatedAt     time.Time     `json:"updated_at"`
	Version       string        `json:"version"`
}

// AgreementKind defines model for AgreementKind.
type AgreementKind string

// AgreementSummary defines model for AgreementSummary.
type AgreementSummary struct {
	ChangeSummary *string       `json:"change_summary,omitempty"`
	Id            int64         `json:"id"`
	Kind          AgreementKind `json:"kind"`
	Title         string        `json:"title"`
	Version       string        `json:"version"`
}

// AnswerNorm defines model for AnswerNorm.
type AnswerNorm struct {
	Elements []NormElement `json:"elements"`

	// Example 高分写法：用户资料里的原文与采分点
	Example *struct {
		KpName          *string  `json:"kp_name,omitempty"`
		OriginalText    *string  `json:"original_text,omitempty"`
		QuestionId      int64    `json:"question_id"`
		ReferenceAnswer *string  `json:"reference_answer,omitempty"`
		RubricPoints    []string `json:"rubric_points"`

		// SourceRef 出处：文件 + 页码
		SourceRef *SourceRef `json:"source_ref,omitempty"`
		Stem      string     `json:"stem"`
	} `json:"example,omitempty"`

	// Last 你上次的写法：最近一次批改过的同题型作答，标出缺了什么
	Last *struct {
		AnswerText string   `json:"answer_text"`
		FullScore  *float32 `json:"full_score,omitempty"`
		GradingId  int64    `json:"grading_id"`
		Missing    []string `json:"missing"`
		QuestionId int64    `json:"question_id"`
		Score      *float32 `json:"score,omitempty"`
		Stem       string   `json:"stem"`
	} `json:"last,omitempty"`

	// PracticeQuestionId 「按结构写一道」用的题
	PracticeQuestionId *int64 `json:"practice_question_id,omitempty"`

	// Qtype single_choice 单选、multi_choice 多选、true_false 判断、fill_blank 填空、term 名词解释、short_answer 简答、
	// discussion 论述、essay 作文、calculation 计算（只能自评）、other 其他
	Qtype QuestionType `json:"qtype"`
	Tips  []string     `json:"tips"`
}

// AppUpdate defines model for AppUpdate.
type AppUpdate struct {
	// DownloadUrl 内测期安卓为安装包地址、iOS 为 TestFlight
	DownloadUrl string `json:"download_url"`

	// Force 当前版本低于最低版本，强制更新（0.6b）
	Force bool `json:"force"`

	// HasUpdate 有新版本（0.6，每个版本提示一次由客户端记录）
	HasUpdate     *bool   `json:"has_update,omitempty"`
	LatestVersion string  `json:"latest_version"`
	MinVersion    string  `json:"min_version"`
	ReleaseNotes  *string `json:"release_notes,omitempty"`
}

// AttemptBrief defines model for AttemptBrief.
type AttemptBrief struct {
	IsCorrect *bool     `json:"is_correct,omitempty"`
	Revealed  bool      `json:"revealed"`
	Selected  *[]string `json:"selected,omitempty"`

	// SelfAssess 不会 / 模糊 / 掌握
	SelfAssess *SelfAssessLevel `json:"self_assess,omitempty"`
}

// AttemptHistory defines model for AttemptHistory.
type AttemptHistory struct {
	AnsweredAt time.Time                  `json:"answered_at"`
	AttemptId  int64                      `json:"attempt_id"`
	FullScore  *float32                   `json:"full_score,omitempty"`
	IsCorrect  *bool                      `json:"is_correct,omitempty"`
	LossTypes  *[]AttemptHistoryLossTypes `json:"loss_types,omitempty"`

	// MissedPoints 遗漏的采分点
	MissedPoints *[]string `json:"missed_points,omitempty"`
	Score        *float32  `json:"score,omitempty"`
}

// AttemptHistoryLossTypes defines model for AttemptHistory.LossTypes.
type AttemptHistoryLossTypes string

// AttemptResult defines model for AttemptResult.
type AttemptResult struct {
	Analysis      *string `json:"analysis,omitempty"`
	AttemptId     int64   `json:"attempt_id"`
	CorrectAnswer *string `json:"correct_answer,omitempty"`

	// IsCorrect 客观题服务端判定；主观题自评不判对错
	IsCorrect *bool           `json:"is_correct,omitempty"`
	KpChanges []MasteryChange `json:"kp_changes"`

	// WrongBook 加入错题本 / 仍在错题本 / 自动移出（已消灭） / 无变化
	WrongBook AttemptResultWrongBook `json:"wrong_book"`
}

// AttemptResultWrongBook 加入错题本 / 仍在错题本 / 自动移出（已消灭） / 无变化
type AttemptResultWrongBook string

